1	"use client";
2	
3	import { useState } from "react";
4	import { useQueryClient } from "@tanstack/react-query";
5	import { supabase } from "@/integrations/supabase/client";
6	import { useSeoSettings } from "@/hooks/useSeoSettings";
7	import { useSeoPages } from "@/hooks/useSeoSettings";
8	import { Button } from "@/components/ui/button";
9	import { Label } from "@/components/ui/label";
10	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
11	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
12	import { Switch } from "@/components/ui/switch";
13	import { toast } from "sonner";
14	import { Save, Loader2, Map, Eye, Copy, ExternalLink } from "lucide-react";
15	import { logAuditAction } from "@/lib/auditLog";
16	
17	const SitemapTab = () => {
18	  const qc = useQueryClient();
19	  const { settings, isLoading } = useSeoSettings();
20	  const { pages } = useSeoPages();
21	  const [saving, setSaving] = useState(false);
22	  const [loaded, setLoaded] = useState(false);
23	  const [showPreview, setShowPreview] = useState(false);
24	
25	  const [form, setForm] = useState({
26	    sitemap_enabled: true,
27	    sitemap_changefreq: "weekly",
28	    sitemap_priority: 0.8,
29	  });
30	
31	  if (settings && !loaded) {
32	    const s = settings as Record<string, unknown>;
33	    setForm({
34	      sitemap_enabled: (s.sitemap_enabled as boolean) ?? true,
35	      sitemap_changefreq: (s.sitemap_changefreq as string) ?? "weekly",
36	      sitemap_priority: (s.sitemap_priority as number) ?? 0.8,
37	    });
38	    setLoaded(true);
39	  }
40	
41	  const save = async () => {
42	    setSaving(true);
43	    try {
44	      const { error } = await (supabase.from as Function)("seo_settings")
45	        .update(form)
46	        .eq("id", settings?.id);
47	      if (error) { toast.error(error.message); return; }
48	      toast.success("Sitemap settings saved");
49	      logAuditAction("seo.update", "seo_settings", settings?.id, { section: "sitemap", ...form });
50	      qc.invalidateQueries({ queryKey: ["seo_settings"] });
51	    } finally {
52	      setSaving(false);
53	    }
54	  };
55	
56	  const baseUrl = settings?.canonical_url || window.location.origin;
57	  const sitemapPages = pages.filter((p) => p.include_in_sitemap && p.is_active);
58	
59	  const generateSitemapXml = () => {
60	    const urls = sitemapPages.map((p) => {
61	      return `  <url>
62	    <loc>${baseUrl}${p.page_path}</loc>
63	    <changefreq>${p.changefreq || form.sitemap_changefreq}</changefreq>
64	    <priority>${p.priority ?? form.sitemap_priority}</priority>
65	  </url>`;
66	    }).join("\n");
67	
68	    return `<?xml version="1.0" encoding="UTF-8"?>
69	<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
70	${urls}
71	</urlset>`;
72	  };
73	
74	  if (isLoading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;
75	
76	  return (
77	    <div className="space-y-4">
78	      <Card>
79	        <CardHeader className="pb-3">
80	          <CardTitle className="text-lg flex items-center gap-2"><Map className="h-5 w-5" /> Sitemap Configuration</CardTitle>
81	          <CardDescription>Configure XML sitemap generation. Individual page settings are managed in the Page SEO tab.</CardDescription>
82	        </CardHeader>
83	        <CardContent className="space-y-4">
84	          <div className="flex items-center gap-3">
85	            <Switch checked={form.sitemap_enabled} onCheckedChange={(v) => setForm({ ...form, sitemap_enabled: v })} />
86	            <Label>Enable Sitemap Generation</Label>
87	          </div>
88	
89	          {form.sitemap_enabled && (
90	            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
91	              <div>
92	                <Label>Default Change Frequency</Label>
93	                <Select value={form.sitemap_changefreq} onValueChange={(v) => setForm({ ...form, sitemap_changefreq: v })}>
94	                  <SelectTrigger><SelectValue /></SelectTrigger>
95	                  <SelectContent>
96	                    <SelectItem value="always">always</SelectItem>
97	                    <SelectItem value="hourly">hourly</SelectItem>
98	                    <SelectItem value="daily">daily</SelectItem>
99	                    <SelectItem value="weekly">weekly</SelectItem>
100	                    <SelectItem value="monthly">monthly</SelectItem>
101	                    <SelectItem value="yearly">yearly</SelectItem>
102	                    <SelectItem value="never">never</SelectItem>
103	                  </SelectContent>
104	                </Select>
105	              </div>
106	              <div>
107	                <Label>Default Priority (0.0 - 1.0)</Label>
108	                <Select value={String(form.sitemap_priority)} onValueChange={(v) => setForm({ ...form, sitemap_priority: parseFloat(v) })}>
109	                  <SelectTrigger><SelectValue /></SelectTrigger>
110	                  <SelectContent>
111	                    {[1.0, 0.9, 0.8, 0.7, 0.6, 0.5, 0.4, 0.3, 0.2, 0.1, 0.0].map((v) => (
112	                      <SelectItem key={v} value={String(v)}>{v.toFixed(1)}</SelectItem>
113	                    ))}
114	                  </SelectContent>
115	                </Select>
116	              </div>
117	            </div>
118	          )}
119	
120	          {form.sitemap_enabled && (
121	            <div className="rounded-md border p-3 bg-muted/50">
122	              <p className="text-sm font-medium mb-1">Pages in Sitemap: {sitemapPages.length}</p>
123	              <div className="flex flex-wrap gap-1">
124	                {sitemapPages.map((p) => (
125	                  <span key={p.id} className="text-xs bg-primary/10 text-primary px-2 py-0.5 rounded">{p.page_path}</span>
126	                ))}
127	              </div>
128	            </div>
129	          )}
130	        </CardContent>
131	      </Card>
132	
133	      {form.sitemap_enabled && (
134	        <Card>
135	          <CardHeader className="pb-3">
136	            <div className="flex items-center justify-between">
137	              <CardTitle className="text-lg">Sitemap Preview</CardTitle>
138	              <Button variant="outline" size="sm" onClick={() => setShowPreview(!showPreview)}>
139	                <Eye className="h-3 w-3 mr-1" /> {showPreview ? "Hide" : "Show"} Preview
140	              </Button>
141	            </div>
142	          </CardHeader>
143	          {showPreview && (
144	            <CardContent>
145	              <pre className="text-xs font-mono bg-muted p-3 rounded-md overflow-auto max-h-64 whitespace-pre-wrap">
146	                {generateSitemapXml()}
147	              </pre>
148	            </CardContent>
149	          )}
150	        </Card>
151	      )}
152	
153	      <Button onClick={save} disabled={saving}>
154	        {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
155	        Save Sitemap Settings
156	      </Button>
157	
158	      {/* Live endpoint info */}
159	      <Card className="border-dashed bg-muted/30">
160	        <CardHeader className="pb-2 pt-4">
161	          <CardTitle className="text-sm">Dynamic Endpoint</CardTitle>
162	          <CardDescription className="text-xs">
163	            The sitemap is served live from this Supabase Edge Function URL and reflects your current page settings.
164	            Configure a rewrite rule on your production domain so <code className="bg-muted px-1 rounded text-xs">/sitemap.xml</code> proxies to this endpoint, or reference it directly.
165	          </CardDescription>
166	        </CardHeader>
167	        <CardContent className="pb-4 space-y-2">
168	          <div className="flex items-center gap-2 rounded-md bg-muted px-3 py-2">
169	            <code className="text-xs font-mono flex-1 break-all text-muted-foreground">
170	              {`${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/serve-sitemap`}
171	            </code>
172	            <Button
173	              variant="ghost" size="icon" className="h-7 w-7 shrink-0"
174	              onClick={() => { navigator.clipboard.writeText(`${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/serve-sitemap`); toast.success("URL copied"); }}
175	            >
176	              <Copy className="h-3.5 w-3.5" />
177	            </Button>
178	            <Button variant="ghost" size="icon" className="h-7 w-7 shrink-0" asChild>
179	              <a href={`${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/serve-sitemap`} target="_blank" rel="noopener noreferrer">
180	                <ExternalLink className="h-3.5 w-3.5" />
181	              </a>
182	            </Button>
183	          </div>
184	        </CardContent>
185	      </Card>
186	    </div>
187	  );
188	};
189	
190	export default SitemapTab;
