1	"use client";
2	
3	import { useEffect } from "react";
4	import { usePathname } from "next/navigation";
5	import { useSeoSettings, useSeoPages } from "@/hooks/useSeoSettings";
6	
7	/**
8	 * Dynamic SEO head manager.
9	 * Updates document meta tags based on admin-configured SEO settings.
10	 * Supports per-page overrides that fall back to global settings.
11	 */
12	const SeoHead = () => {
13	  const pathname = usePathname() ?? "/";
14	  const { settings } = useSeoSettings();
15	  const { pages } = useSeoPages();
16	
17	  useEffect(() => {
18	    if (!settings) return;
19	
20	    const currentPage = pages.find((p) => p.page_path === pathname && p.is_active);
21	
22	    // Resolve with per-page overrides falling back to global
23	    const title = currentPage?.title || settings.site_title || "Rankora";
24	    const description = currentPage?.description || settings.site_description || "";
25	    const keywords = currentPage?.keywords || settings.site_keywords || "";
26	    const robots = currentPage?.meta_robots || settings.meta_robots || "index, follow";
27	    // Per-page canonical is used as-is; global canonical is a base URL + current path
28	    const canonicalBase = (settings.canonical_url || "").replace(/\/$/, "");
29	    const canonical = currentPage?.canonical_url ||
30	      (canonicalBase ? `${canonicalBase}${pathname}` : "");
31	    const ogTitle = currentPage?.og_title || settings.og_title || title;
32	    const ogDescription = currentPage?.og_description || settings.og_description || description;
33	    const ogImage = currentPage?.og_image_url || settings.og_image_url || "";
34	    const ogType = settings.og_type || "website";
35	    const ogSiteName = settings.og_site_name || settings.site_title || "";
36	    const twitterCard = settings.twitter_card || "summary_large_image";
37	    const twitterSite = settings.twitter_site || "";
38	    const twitterCreator = settings.twitter_creator || "";
39	    const twitterImage = settings.twitter_image_url || ogImage;
40	
41	    // Update document title
42	    document.title = title;
43	
44	    // Helper to set/remove a meta tag
45	    const setMeta = (attr: string, key: string, content: string) => {
46	      if (!content) {
47	        const existing = document.querySelector(`meta[${attr}="${key}"]`);
48	        if (existing) existing.remove();
49	        return;
50	      }
51	      let el = document.querySelector(`meta[${attr}="${key}"]`) as HTMLMetaElement;
52	      if (!el) {
53	        el = document.createElement("meta");
54	        el.setAttribute(attr, key);
55	        document.head.appendChild(el);
56	      }
57	      el.setAttribute("content", content);
58	    };
59	
60	    // Standard meta
61	    setMeta("name", "description", description);
62	    setMeta("name", "keywords", keywords);
63	    setMeta("name", "robots", robots);
64	    setMeta("name", "theme-color", settings.theme_color || "");
65	
66	    // Bot-specific meta
67	    if (settings.googlebot) setMeta("name", "googlebot", settings.googlebot);
68	    if (settings.bingbot) setMeta("name", "bingbot", settings.bingbot);
69	
70	    // Verification meta
71	    if (settings.google_search_console_id) setMeta("name", "google-site-verification", settings.google_search_console_id);
72	    if (settings.bing_webmaster_id) setMeta("name", "msvalidate.01", settings.bing_webmaster_id);
73	
74	    // Open Graph
75	    setMeta("property", "og:title", ogTitle);
76	    setMeta("property", "og:description", ogDescription);
77	    setMeta("property", "og:image", ogImage);
78	    setMeta("property", "og:type", ogType);
79	    setMeta("property", "og:site_name", ogSiteName);
80	    if (canonical) setMeta("property", "og:url", canonical);
81	    if (settings.facebook_app_id) setMeta("property", "fb:app_id", settings.facebook_app_id);
82	
83	    // Twitter Card
84	    setMeta("name", "twitter:card", twitterCard);
85	    setMeta("name", "twitter:title", ogTitle);
86	    setMeta("name", "twitter:description", ogDescription);
87	    setMeta("name", "twitter:image", twitterImage);
88	    if (twitterSite) setMeta("name", "twitter:site", twitterSite);
89	    if (twitterCreator) setMeta("name", "twitter:creator", twitterCreator);
90	
91	    // Sitemap link (always points to /sitemap.xml on the same domain)
92	    if (!document.querySelector('link[rel="sitemap"]')) {
93	      const linkSitemap = document.createElement("link");
94	      linkSitemap.setAttribute("rel", "sitemap");
95	      linkSitemap.setAttribute("type", "application/xml");
96	      linkSitemap.setAttribute("title", "Sitemap");
97	      linkSitemap.setAttribute("href", "/sitemap.xml");
98	      document.head.appendChild(linkSitemap);
99	    }
100	
101	    // Canonical link
102	    let linkCanonical = document.querySelector('link[rel="canonical"]') as HTMLLinkElement;
103	    if (canonical) {
104	      if (!linkCanonical) {
105	        linkCanonical = document.createElement("link");
106	        linkCanonical.setAttribute("rel", "canonical");
107	        document.head.appendChild(linkCanonical);
108	      }
109	      linkCanonical.setAttribute("href", canonical);
110	    } else if (linkCanonical) {
111	      linkCanonical.remove();
112	    }
113	
114	    // Structured Data (JSON-LD)
115	    const existingLd = document.getElementById("seo-jsonld");
116	    if (settings.structured_data_enabled) {
117	      const schemas: Record<string, any>[] = [];
118	
119	      // Organization schema
120	      const org: Record<string, any> = {
121	        "@context": "https://schema.org",
122	        "@type": "Organization",
123	        name: settings.organization_name || settings.site_title || "Rankora",
124	        description: settings.organization_description || description,
125	      };
126	      if (settings.organization_url) org.url = settings.organization_url;
127	      if (settings.organization_logo_url) org.logo = settings.organization_logo_url;
128	      schemas.push(org);
129	
130	      // WebApplication schema
131	      const webapp: Record<string, any> = {
132	        "@context": "https://schema.org",
133	        "@type": "WebApplication",
134	        name: settings.site_title || "Rankora",
135	        description: description,
136	        applicationCategory: "BusinessApplication",
137	        operatingSystem: "Web",
138	      };
139	      if (settings.organization_url) webapp.url = settings.organization_url;
140	      schemas.push(webapp);
141	
142	      // Per-page structured data
143	      if (currentPage?.structured_data_json && Object.keys(currentPage.structured_data_json).length > 0) {
144	        schemas.push(currentPage.structured_data_json);
145	      }
146	
147	      const script = existingLd || document.createElement("script");
148	      script.setAttribute("type", "application/ld+json");
149	      script.id = "seo-jsonld";
150	      script.textContent = JSON.stringify(schemas);
151	      if (!existingLd) document.head.appendChild(script);
152	    } else if (existingLd) {
153	      existingLd.remove();
154	    }
155	
156	    // ── AEO (Answer Engine Optimization) ──────────────────────────────────
157	    // Remove existing AEO script so it can be replaced cleanly on updates
158	    document.getElementById("seo-aeo-faq-jsonld")?.remove();
159	    if (settings.aeo_enabled) {
160	      const faqItems = Array.isArray(settings.aeo_faq_json) ? settings.aeo_faq_json : [];
161	
162	      if (faqItems.length > 0) {
163	        const faqSchema = {
164	          "@context": "https://schema.org",
165	          "@type": "FAQPage",
166	          mainEntity: faqItems.map((item: { q: string; a: string }) => ({
167	            "@type": "Question",
168	            name: item.q,
169	            acceptedAnswer: { "@type": "Answer", text: item.a },
170	          })),
171	        };
172	        const faqScript = document.createElement("script");
173	        faqScript.setAttribute("type", "application/ld+json");
174	        faqScript.id = "seo-aeo-faq-jsonld";
175	        faqScript.textContent = JSON.stringify(faqSchema);
176	        document.head.appendChild(faqScript);
177	      }
178	
179	      // Re-inject the main seo-jsonld WebApplication schema with speakable if enabled
180	      if (settings.aeo_speakable_enabled && settings.structured_data_enabled) {
181	        const existingLdScript = document.getElementById("seo-jsonld");
182	        if (existingLdScript) {
183	          try {
184	            const schemas = JSON.parse(existingLdScript.textContent || "[]") as Record<string, any>[];
185	            const webappIdx = schemas.findIndex((s) => s["@type"] === "WebApplication");
186	            if (webappIdx !== -1) {
187	              schemas[webappIdx].speakable = {
188	                "@type": "SpeakableSpecification",
189	                cssSelector: ["h1", "h2", ".speakable"],
190	              };
191	              existingLdScript.textContent = JSON.stringify(schemas);
192	            }
193	          } catch {
194	            // JSON parse failed — leave schema as-is
195	          }
196	        }
197	      }
198	    }
199	
200	    // ── GEO (Generative Engine Optimization) ──────────────────────────────
201	    const currentYear = new Date().getFullYear().toString();
202	    const siteTitle = settings.site_title || "Rankora";
203	
204	    if (settings.geo_enabled) {
205	      setMeta("name", "generator", "Rankora");
206	      if (settings.geo_author_name) {
207	        setMeta("name", "citation_author", settings.geo_author_name);
208	      } else {
209	        document.querySelector('meta[name="citation_author"]')?.remove();
210	      }
211	      setMeta("name", "citation_publication_date", currentYear);
212	      if (settings.geo_site_description_for_ai) {
213	        setMeta("name", "description_ai", settings.geo_site_description_for_ai);
214	      } else {
215	        document.querySelector('meta[name="description_ai"]')?.remove();
216	      }
217	      if (settings.geo_citations_enabled) {
218	        setMeta("name", "citation_title", siteTitle);
219	        setMeta("name", "robots", "max-snippet:-1, max-image-preview:large, index, follow");
220	      } else {
221	        document.querySelector('meta[name="citation_title"]')?.remove();
222	      }
223	    } else {
224	      // Clean up GEO meta tags if disabled
225	      ["generator", "citation_author", "citation_publication_date", "description_ai", "citation_title"]
226	        .forEach((name) => document.querySelector(`meta[name="${name}"]`)?.remove());
227	    }
228	
229	    // Google Analytics — reinject if ID changes or was removed
230	    const existingGaScript = document.getElementById("ga-script") as HTMLScriptElement | null;
231	    if (settings.google_analytics_id) {
232	      const newSrc = `https://www.googletagmanager.com/gtag/js?id=${settings.google_analytics_id}`;
233	      if (existingGaScript && existingGaScript.src !== newSrc) {
234	        // GA ID changed — remove old scripts so they get recreated
235	        existingGaScript.remove();
236	        document.getElementById("ga-init")?.remove();
237	      }
238	      if (!document.getElementById("ga-script")) {
239	        const gaScript = document.createElement("script");
240	        gaScript.id = "ga-script";
241	        gaScript.async = true;
242	        gaScript.src = newSrc;
243	        document.head.appendChild(gaScript);
244	        const gaInit = document.createElement("script");
245	        gaInit.id = "ga-init";
246	        gaInit.textContent = `window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag('js',new Date());gtag('config','${settings.google_analytics_id}');`;
247	        document.head.appendChild(gaInit);
248	      }
249	    } else {
250	      // GA ID cleared — clean up scripts
251	      document.getElementById("ga-script")?.remove();
252	      document.getElementById("ga-init")?.remove();
253	    }
254	  }, [settings, pages, pathname]);
255	
256	  return null;
257	};
